-- FAQ admissions are per entry. Legacy rows receive versions only.
CREATE TABLE faq_catalog_input_origins (knowledge_id TEXT PRIMARY KEY,producer_id TEXT NOT NULL,origin_kind TEXT NOT NULL CHECK(origin_kind='trusted_code'),input_digest TEXT NOT NULL CHECK(length(input_digest)=64),revision BIGINT NOT NULL CHECK(revision>0));
CREATE TABLE faq_catalog_control_versions (knowledge_id TEXT PRIMARY KEY,revision BIGINT NOT NULL CHECK(revision>0));
CREATE TABLE faq_input_row_versions (chunk_id TEXT PRIMARY KEY, revision BIGINT NOT NULL CHECK(revision>0));
CREATE TABLE faq_input_scope_versions (tenant_id BIGINT NOT NULL,knowledge_base_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),PRIMARY KEY(tenant_id,knowledge_base_id));
CREATE TABLE faq_input_sessions (id TEXT PRIMARY KEY,tenant_id BIGINT NOT NULL,knowledge_base_id TEXT NOT NULL,operation TEXT NOT NULL,input_digest TEXT NOT NULL,input_body TEXT NOT NULL,origin_kind TEXT NOT NULL,source_lineage TEXT NOT NULL,original_inputs TEXT NOT NULL,original_snapshot TEXT NOT NULL,current_snapshot TEXT NOT NULL);
CREATE TABLE faq_input_actor_selectors (admission_id TEXT PRIMARY KEY REFERENCES faq_input_sessions(id),caller_tenant_id BIGINT NOT NULL,user_id TEXT NOT NULL,principal_type TEXT NOT NULL,principal_id TEXT NOT NULL,api_key_id BIGINT);
CREATE TABLE faq_entry_input_admissions (id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES faq_input_sessions(id),tenant_id BIGINT NOT NULL,knowledge_base_id TEXT NOT NULL,knowledge_id TEXT NOT NULL,chunk_id TEXT NOT NULL,input_digest TEXT NOT NULL,config_digest TEXT NOT NULL,config_revision BIGINT NOT NULL,source_lineage TEXT NOT NULL);
CREATE TABLE faq_entry_material_receipts (chunk_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES faq_entry_input_admissions(id),revision BIGINT NOT NULL,body_digest TEXT NOT NULL);
INSERT INTO faq_input_row_versions(chunk_id,revision) SELECT id,1 FROM chunks WHERE chunk_type='faq';
INSERT INTO faq_input_scope_versions(tenant_id,knowledge_base_id,revision) SELECT tenant_id,id,1 FROM knowledge_bases;
CREATE TRIGGER faq_entry_input_admissions_immutable_update BEFORE UPDATE ON faq_entry_input_admissions BEGIN SELECT RAISE(ABORT,'immutable FAQ input'); END;
CREATE TRIGGER faq_entry_input_admissions_immutable_delete BEFORE DELETE ON faq_entry_input_admissions BEGIN SELECT RAISE(ABORT,'immutable FAQ input'); END;
CREATE TRIGGER faq_input_sessions_immutable_update BEFORE UPDATE ON faq_input_sessions WHEN OLD.id IS NOT NEW.id OR OLD.tenant_id IS NOT NEW.tenant_id OR OLD.knowledge_base_id IS NOT NEW.knowledge_base_id OR OLD.operation IS NOT NEW.operation OR OLD.input_digest IS NOT NEW.input_digest OR OLD.input_body IS NOT NEW.input_body OR OLD.origin_kind IS NOT NEW.origin_kind OR OLD.source_lineage IS NOT NEW.source_lineage OR OLD.original_inputs IS NOT NEW.original_inputs OR OLD.original_snapshot IS NOT NEW.original_snapshot BEGIN SELECT RAISE(ABORT,'immutable FAQ session input'); END;
CREATE TRIGGER faq_input_chunk_insert AFTER INSERT ON chunks WHEN NEW.chunk_type='faq' BEGIN INSERT INTO faq_input_row_versions(chunk_id,revision) VALUES(NEW.id,1) ON CONFLICT(chunk_id) DO UPDATE SET revision=revision+1; INSERT INTO faq_input_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER faq_input_chunk_update AFTER UPDATE ON chunks WHEN NEW.chunk_type='faq' BEGIN INSERT INTO faq_input_row_versions(chunk_id,revision) VALUES(NEW.id,1) ON CONFLICT(chunk_id) DO UPDATE SET revision=revision+1; INSERT INTO faq_input_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER faq_input_chunk_delete AFTER DELETE ON chunks WHEN OLD.chunk_type='faq' BEGIN INSERT INTO faq_input_row_versions(chunk_id,revision) VALUES(OLD.id,1) ON CONFLICT(chunk_id) DO UPDATE SET revision=revision+1; INSERT INTO faq_input_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER faq_input_chunk_move AFTER UPDATE ON chunks WHEN OLD.chunk_type='faq' AND (OLD.tenant_id IS NOT NEW.tenant_id OR OLD.knowledge_base_id IS NOT NEW.knowledge_base_id OR OLD.chunk_type IS NOT NEW.chunk_type) BEGIN INSERT INTO faq_input_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(OLD.tenant_id,OLD.knowledge_base_id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER faq_input_kb_insert AFTER INSERT ON knowledge_bases BEGIN INSERT INTO faq_input_scope_versions(tenant_id,knowledge_base_id,revision) VALUES(NEW.tenant_id,NEW.id,1) ON CONFLICT(tenant_id,knowledge_base_id) DO UPDATE SET revision=revision+1; END;

CREATE TRIGGER faq_catalog_input_origins_immutable_update BEFORE UPDATE ON faq_catalog_input_origins BEGIN SELECT RAISE(ABORT,'immutable FAQ catalog origin'); END;
CREATE TRIGGER faq_catalog_input_origins_immutable_delete BEFORE DELETE ON faq_catalog_input_origins BEGIN SELECT RAISE(ABORT,'immutable FAQ catalog origin'); END;

CREATE TRIGGER faq_input_actor_selectors_immutable_update BEFORE UPDATE ON faq_input_actor_selectors BEGIN SELECT RAISE(ABORT,'immutable FAQ original actor'); END;
CREATE TRIGGER faq_input_actor_selectors_immutable_delete BEFORE DELETE ON faq_input_actor_selectors BEGIN SELECT RAISE(ABORT,'immutable FAQ original actor'); END;

INSERT INTO faq_catalog_control_versions(knowledge_id,revision) SELECT id,1 FROM knowledges WHERE type='faq';
CREATE TRIGGER faq_catalog_control_insert AFTER INSERT ON knowledges WHEN NEW.type='faq' BEGIN INSERT INTO faq_catalog_control_versions(knowledge_id,revision) VALUES(NEW.id,1) ON CONFLICT(knowledge_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER faq_catalog_control_update AFTER UPDATE ON knowledges WHEN (OLD.type='faq' OR NEW.type='faq') AND (OLD.parse_status IS NOT NEW.parse_status OR OLD.enable_status IS NOT NEW.enable_status) BEGIN INSERT INTO faq_catalog_control_versions(knowledge_id,revision) VALUES(NEW.id,1) ON CONFLICT(knowledge_id) DO UPDATE SET revision=revision+1; END;

-- Actual import progress/result producers retain their own immutable bodies.
CREATE TABLE faq_import_output_admissions (id TEXT PRIMARY KEY,output_key TEXT NOT NULL,session_id TEXT NOT NULL REFERENCES faq_input_sessions(id),tenant_id BIGINT NOT NULL,knowledge_base_id TEXT NOT NULL,knowledge_id TEXT NOT NULL,task_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('progress','result')),body_digest TEXT NOT NULL CHECK(length(body_digest)=64),body TEXT NOT NULL,source_lineage TEXT NOT NULL,original_inputs TEXT NOT NULL,material_revision BIGINT NOT NULL);
CREATE TABLE faq_import_output_heads (output_key TEXT PRIMARY KEY,admission_id TEXT NOT NULL REFERENCES faq_import_output_admissions(id),revision BIGINT NOT NULL CHECK(revision>0));
CREATE TABLE faq_import_result_versions (knowledge_id TEXT PRIMARY KEY,revision BIGINT NOT NULL CHECK(revision>0));
INSERT INTO faq_import_result_versions(knowledge_id,revision) SELECT id,1 FROM knowledges WHERE type='faq';
CREATE TRIGGER faq_import_output_admissions_immutable_update BEFORE UPDATE ON faq_import_output_admissions BEGIN SELECT RAISE(ABORT,'immutable FAQ import output'); END;
CREATE TRIGGER faq_import_output_admissions_immutable_delete BEFORE DELETE ON faq_import_output_admissions BEGIN SELECT RAISE(ABORT,'immutable FAQ import output'); END;
CREATE TRIGGER faq_import_result_insert AFTER INSERT ON knowledges WHEN NEW.type='faq' BEGIN INSERT INTO faq_import_result_versions(knowledge_id,revision) VALUES(NEW.id,1) ON CONFLICT(knowledge_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER faq_import_result_update AFTER UPDATE ON knowledges WHEN (OLD.type='faq' OR NEW.type='faq') AND (OLD.last_faq_import_result IS NOT NEW.last_faq_import_result OR OLD.tenant_id IS NOT NEW.tenant_id OR OLD.knowledge_base_id IS NOT NEW.knowledge_base_id OR OLD.deleted_at IS NOT NEW.deleted_at) BEGIN INSERT INTO faq_import_result_versions(knowledge_id,revision) VALUES(NEW.id,1) ON CONFLICT(knowledge_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER faq_import_result_delete AFTER DELETE ON knowledges WHEN OLD.type='faq' BEGIN INSERT INTO faq_import_result_versions(knowledge_id,revision) VALUES(OLD.id,1) ON CONFLICT(knowledge_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER faq_import_output_head_monotonic BEFORE UPDATE ON faq_import_output_heads WHEN NEW.revision!=OLD.revision+1 BEGIN SELECT RAISE(ABORT,'FAQ output head revision must advance'); END;
